from pathlib import Path
import json
from playwright.sync_api import sync_playwright
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.add_script_tag(content=Path('experimental/worker/archive-endpoint.js').read_text())
 result=p.evaluate('''async()=>{let epoch=1,writes=0,replies=[],release;const gate=new Promise(r=>release=r);const endpoint=createWorkerArchiveEndpoint({epoch:()=>epoch,export:async()=>{await gate;return {archive:'canonical'};},save:async()=>{writes++;return {persisted:true};},restore:async(text,commit)=>{await new Promise(r=>setTimeout(r,10));commit();epoch++;return {restored:true};},complete:r=>replies.push(r)});
 const accepted=endpoint.submit({id:1,epoch:1,op:'export'}),duplicate=endpoint.submit({id:1,epoch:1,op:'save'});endpoint.submit({id:2,epoch:1,op:'save'});const cancelled=endpoint.cancel(2);release();await new Promise(r=>setTimeout(r,30));if(!accepted.accepted||duplicate.accepted||!cancelled.cancelled||writes!==0||replies[1].ok)throw Error('duplicate/cancel failure');
 endpoint.submit({id:3,epoch:1,op:'restore',archive:'candidate'});endpoint.submit({id:4,epoch:1,op:'save'});await new Promise(r=>setTimeout(r,40));if(!replies[2].ok||replies[3].ok||writes!==0||epoch!==2)throw Error('save/load race');const guarded=createWorkerArchiveEndpoint({session:()=> 'new-session',epoch:()=>2,complete:()=>{}});const stale=guarded.submit({id:99,session:'old-session',epoch:2,op:'export'});if(stale.accepted||guarded.status().lastId!==0||guarded.cancel(1,'old-session').reason!=='STALE_SESSION')throw Error('stale session consumed current IDs');return {staleSessionRejectedBeforeIdConsumption:true,delayedReply:true,duplicateRejected:true,cancelledSaveNoWrites:true,oldEpochSaveAfterRestoreRejected:true,replies};}''')
 Path('experimental/worker/archive-endpoint-proof.json').write_text(json.dumps(result,indent=2));print('PASS delayed replies, duplicates, cancellation and save/load race');b.close()
